class Node:
    def __init__(self, key: int = -1, val: int = -1, nextt: Optional["Node"] = None, prev: Optional["Node"] = None):
        self.key = key
        self.val = val
        self.next = nextt
        self.prev = prev

class LinkedList:

    def __init__(self):
        self.head = Node()
        self.tail = Node()

        self.head.next = self.tail
        self.tail.prev = self.head

    def addHead(self, node: Node) -> None:
        headNext = self.head.next
        node.next = headNext
        node.prev = self.head
        self.head.next= node
        headNext.prev = node

    def removeTail(self) -> Optional["Node"]:
        if self.tail.prev == self.head:
            return None

        removedNode = self.tail.prev
        self.remove(removedNode)
        return removedNode

    def remove(self, node: Node) -> None:
        prev = node.prev
        nextt = node.next

        prev.next = nextt
        nextt.prev = prev

        node.next = None
        node.prev = None

class LRUCache:

    def __init__(self, capacity: int):
        self.cap = capacity
        # key -> key, value -> Node
        self.hashmap = {}
        self.list = LinkedList()

    def size(self) -> int:
        return len(self.hashmap)

    def get(self, key: int) -> int:
        if key not in self.hashmap:
            return -1

        node = self.hashmap[key]
        self.updateRecentlyUsed(node)
        return node.val

    def put(self, key: int, value: int) -> None:
        if key not in self.hashmap:
            self.hashmap[key] = Node(key, value)
            self.list.addHead(self.hashmap[key])
        else:
            node = self.hashmap[key]
            node.val = value
            self.updateRecentlyUsed(node)

        if self.size() > self.cap:
            self.evict()

    def updateRecentlyUsed(self, node: Node) -> None:
        self.list.remove(node)
        self.list.addHead(node)

    def evict(self) -> None:
        removedNode = self.list.removeTail()
        del self.hashmap[removedNode.key]
